package com.training.attendance;

import org.springframework.boot.*;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.*;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Component;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;
import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
import org.springframework.web.servlet.HandlerInterceptor;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.persistence.*;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.*;

@SpringBootApplication
public class AttendanceApplication {
 public static void main(String[] args){SpringApplication.run(AttendanceApplication.class,args);}
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean CommandLineRunner seed(UserRepository users, StudentRepository students, FacultyRepository faculty, AttendanceRepository attendance, PasswordEncoder encoder){return args->{
  if(users.count()==0){users.save(new AppUser("admin",encoder.encode("admin123"),"ADMIN"));users.save(new AppUser("faculty",encoder.encode("faculty123"),"FACULTY"));}
  if(students.count()==0){students.save(new Student("TT001","Aarav Sharma","aarav@example.com","Computer Science",2025,"A"));students.save(new Student("TT002","Diya Patel","diya@example.com","Computer Science",2025,"A"));students.save(new Student("TT003","Kabir Rao","kabir@example.com","Electronics",2024,"B"));}
  if(faculty.count()==0)faculty.save(new Faculty("FAC001","Meera Iyer","meera@example.com","Computer Science","faculty"));
  if(attendance.count()==0){List<Student> seeded=students.findAll();LocalDate day=LocalDate.now();if(seeded.size()>=3){attendance.save(new Attendance(seeded.get(0),day,AttendanceStatus.PRESENT));attendance.save(new Attendance(seeded.get(1),day,AttendanceStatus.LATE));attendance.save(new Attendance(seeded.get(2),day,AttendanceStatus.ABSENT));attendance.save(new Attendance(seeded.get(0),day.minusDays(1),AttendanceStatus.PRESENT));attendance.save(new Attendance(seeded.get(1),day.minusDays(1),AttendanceStatus.PRESENT));}}
 };}
}

@Entity @Table(name="users") class AppUser {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(unique=true,nullable=false) String username; @Column(nullable=false) String password; String role; protected AppUser(){} AppUser(String u,String p,String r){username=u;password=p;role=r;}}
@Entity @Table(name="students") class Student {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(unique=true,nullable=false) String rollNumber; @Column(nullable=false) String name; String email; String department; Integer year; String section; protected Student(){} Student(String r,String n,String e,String d,Integer y,String s){rollNumber=r;name=n;email=e;department=d;year=y;section=s;} public Long getId(){return id;} public String getRollNumber(){return rollNumber;} public String getName(){return name;} public String getEmail(){return email;} public String getDepartment(){return department;} public Integer getYear(){return year;} public String getSection(){return section;}}
@Entity @Table(name="faculty") class Faculty {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(unique=true,nullable=false) String facultyId; @Column(nullable=false) String name; String email; String department; String username; protected Faculty(){} Faculty(String i,String n,String e,String d,String u){facultyId=i;name=n;email=e;department=d;username=u;} public Long getId(){return id;} public String getFacultyId(){return facultyId;} public String getName(){return name;} public String getEmail(){return email;} public String getDepartment(){return department;} public String getUsername(){return username;}}
@Entity @Table(name="attendance",uniqueConstraints=@UniqueConstraint(columnNames={"student_id","attendance_date"})) class Attendance {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(optional=false) @JoinColumn(name="student_id") Student student; @Column(name="attendance_date",nullable=false) LocalDate date; @Enumerated(EnumType.STRING) @Column(nullable=false) AttendanceStatus status; protected Attendance(){} Attendance(Student s,LocalDate d,AttendanceStatus st){student=s;date=d;status=st;} public Long getId(){return id;} public Student getStudent(){return student;} public LocalDate getDate(){return date;} public AttendanceStatus getStatus(){return status;}}
enum AttendanceStatus {PRESENT,ABSENT,LATE}
@Component class AuthTokens {private final Map<String,String> roles=new java.util.concurrent.ConcurrentHashMap<>();String issue(String role){String token=UUID.randomUUID().toString();roles.put(token,role);return token;}String role(String token){return roles.get(token);}}
@Configuration class ApiSecurityConfig implements WebMvcConfigurer {private final AuthTokens tokens;ApiSecurityConfig(AuthTokens t){tokens=t;}@Override public void addInterceptors(InterceptorRegistry registry){registry.addInterceptor(new HandlerInterceptor(){@Override public boolean preHandle(HttpServletRequest request,HttpServletResponse response,Object handler)throws java.io.IOException{if("OPTIONS".equals(request.getMethod()))return true;String auth=request.getHeader("Authorization");String role=auth!=null&&auth.startsWith("Bearer ")?tokens.role(auth.substring(7)):null;if(role==null){response.setStatus(401);response.setContentType("application/json");response.getWriter().write("{\"error\":\"Please sign in to continue\"}");return false;}String path=request.getRequestURI(),method=request.getMethod();boolean adminOnly=(path.startsWith("/api/students")||path.startsWith("/api/faculty"))&&!method.equals("GET")||path.equals("/api/faculty")&&method.equals("POST");if(adminOnly&&!"ADMIN".equals(role)){response.setStatus(403);response.setContentType("application/json");response.getWriter().write("{\"error\":\"Admin access required\"}");return false;}return true;}}).addPathPatterns("/api/**").excludePathPatterns("/api/auth/**");}}
interface UserRepository extends JpaRepository<AppUser,Long>{Optional<AppUser> findByUsername(String username);}
interface StudentRepository extends JpaRepository<Student,Long>{@Query("select s from Student s where lower(s.name) like lower(concat('%',:q,'%')) or lower(s.rollNumber) like lower(concat('%',:q,'%'))") List<Student> search(@Param("q") String q);}
interface FacultyRepository extends JpaRepository<Faculty,Long>{}
interface AttendanceRepository extends JpaRepository<Attendance,Long>{List<Attendance> findByDate(LocalDate date);List<Attendance> findByStudentId(Long id);List<Attendance> findByDateBetween(LocalDate start,LocalDate end);boolean existsByStudentIdAndDate(Long id,LocalDate date);List<Attendance> findByStudentDepartmentAndDateBetween(String department,LocalDate start,LocalDate end);}

record LoginRequest(@NotBlank String username,@NotBlank String password){}
record SignupRequest(@NotBlank @Size(min=3,max=40) String username,@NotBlank @Size(min=8,max=72) String password){}
record LoginResponse(String username,String role,String displayName,String token){}
record StudentRequest(@NotBlank String rollNumber,@NotBlank String name,@Email String email,@NotBlank String department,@NotNull @Min(1) Integer year,@NotBlank String section){}
record FacultyRequest(@NotBlank String facultyId,@NotBlank String name,@Email String email,@NotBlank String department,@NotBlank String username,String password){}
record AttendanceItem(@NotNull Long studentId,@NotNull AttendanceStatus status){}
record BulkAttendance(@NotNull LocalDate date,@NotEmpty List<@Valid AttendanceItem> records){}
@RestControllerAdvice class ApiErrors {@ExceptionHandler(IllegalArgumentException.class) ResponseEntity<Map<String,String>> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));}@ExceptionHandler(NoSuchElementException.class) ResponseEntity<Map<String,String>> missing(NoSuchElementException e){return ResponseEntity.status(404).body(Map.of("error",e.getMessage()));}@ExceptionHandler(org.springframework.dao.DataIntegrityViolationException.class) ResponseEntity<Map<String,String>> duplicate(Exception e){return ResponseEntity.status(409).body(Map.of("error","Duplicate value or attendance already exists."));}}
@RestController @RequestMapping("/api/auth") @CrossOrigin(originPatterns={"http://localhost:[*]","http://127.0.0.1:[*]"}) class AuthController {final UserRepository users;final PasswordEncoder encoder;final AuthTokens tokens; AuthController(UserRepository u,PasswordEncoder p,AuthTokens t){users=u;encoder=p;tokens=t;} @PostMapping("/login") ResponseEntity<?> login(@Valid @RequestBody LoginRequest req){return users.findByUsername(req.username()).filter(u->encoder.matches(req.password(),u.password)).<ResponseEntity<?>>map(u->ResponseEntity.ok(new LoginResponse(u.username,u.role,u.username,tokens.issue(u.role)))).orElseGet(()->ResponseEntity.status(401).body(Map.of("error","Invalid username or password")));} @PostMapping("/register") ResponseEntity<?> register(@Valid @RequestBody SignupRequest req){if(users.findByUsername(req.username()).isPresent())return ResponseEntity.status(409).body(Map.of("error","That username is already taken"));users.save(new AppUser(req.username(),encoder.encode(req.password()),"FACULTY"));return ResponseEntity.status(201).body(Map.of("message","Faculty account created"));}}
@RestController @RequestMapping("/api/students") @CrossOrigin(originPatterns={"http://localhost:[*]","http://127.0.0.1:[*]"}) class StudentController {final StudentRepository repo;StudentController(StudentRepository r){repo=r;}@GetMapping List<Student> all(@RequestParam(defaultValue="") String search){return search.isBlank()?repo.findAll():repo.search(search);}@GetMapping("/{id}") Student one(@PathVariable Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Student not found"));}@PostMapping ResponseEntity<Student> add(@Valid @RequestBody StudentRequest r){Student s=new Student(r.rollNumber(),r.name(),r.email(),r.department(),r.year(),r.section());return ResponseEntity.status(201).body(repo.save(s));}@PutMapping("/{id}") Student update(@PathVariable Long id,@Valid @RequestBody StudentRequest r){Student s=one(id);s.rollNumber=r.rollNumber();s.name=r.name();s.email=r.email();s.department=r.department();s.year=r.year();s.section=r.section();return repo.save(s);}@DeleteMapping("/{id}") ResponseEntity<?> delete(@PathVariable Long id){repo.delete(one(id));return ResponseEntity.noContent().build();}}
@RestController @RequestMapping("/api/faculty") @CrossOrigin(originPatterns={"http://localhost:[*]","http://127.0.0.1:[*]"}) class FacultyController {final FacultyRepository repo;final UserRepository users;final PasswordEncoder encoder;FacultyController(FacultyRepository r,UserRepository u,PasswordEncoder p){repo=r;users=u;encoder=p;}@GetMapping List<Faculty> all(){return repo.findAll();}@PostMapping ResponseEntity<Faculty> add(@Valid @RequestBody FacultyRequest r){if(r.password()==null||r.password().length()<8)throw new IllegalArgumentException("Faculty password must be at least 8 characters");users.save(new AppUser(r.username(),encoder.encode(r.password()),"FACULTY"));return ResponseEntity.status(201).body(repo.save(new Faculty(r.facultyId(),r.name(),r.email(),r.department(),r.username())));}@PutMapping("/{id}") Faculty update(@PathVariable Long id,@Valid @RequestBody FacultyRequest r){Faculty f=repo.findById(id).orElseThrow(()->new NoSuchElementException("Faculty not found"));f.facultyId=r.facultyId();f.name=r.name();f.email=r.email();f.department=r.department();f.username=r.username();return repo.save(f);}@DeleteMapping("/{id}") ResponseEntity<?> delete(@PathVariable Long id){repo.delete(repo.findById(id).orElseThrow(()->new NoSuchElementException("Faculty not found")));return ResponseEntity.noContent().build();}}
@RestController @RequestMapping("/api/attendance") @CrossOrigin(originPatterns={"http://localhost:[*]","http://127.0.0.1:[*]"}) class AttendanceController {final AttendanceRepository repo;final StudentRepository students;AttendanceController(AttendanceRepository r,StudentRepository s){repo=r;students=s;}@GetMapping List<Attendance> all(@RequestParam(required=false) LocalDate date){return date==null?repo.findAll():repo.findByDate(date);}@GetMapping("/student/{id}") List<Attendance> student(@PathVariable Long id){return repo.findByStudentId(id);}@PostMapping("/bulk") ResponseEntity<?> bulk(@Valid @RequestBody BulkAttendance req){for(AttendanceItem i:req.records()){Student s=students.findById(i.studentId()).orElseThrow(()->new NoSuchElementException("Student not found: "+i.studentId()));Optional<Attendance> old=repo.findAll().stream().filter(a->a.student.id.equals(s.id)&&a.date.equals(req.date())).findFirst();if(old.isPresent())old.get().status=i.status();else repo.save(new Attendance(s,req.date(),i.status()));}return ResponseEntity.ok(Map.of("message","Attendance saved","count",req.records().size()));}@PutMapping("/{id}") Attendance update(@PathVariable Long id,@RequestBody AttendanceItem req){Attendance a=repo.findById(id).orElseThrow(()->new NoSuchElementException("Attendance not found"));a.status=req.status();return repo.save(a);}@GetMapping("/reports") List<Attendance> reports(@RequestParam(required=false) Long studentId,@RequestParam(required=false) String department,@RequestParam(required=false) String month){List<Attendance> data;if(month!=null){YearMonth ym=YearMonth.parse(month);data=repo.findByDateBetween(ym.atDay(1),ym.atEndOfMonth());}else data=repo.findAll();return data.stream().filter(a->studentId==null||a.student.id.equals(studentId)).filter(a->department==null||a.student.department.equalsIgnoreCase(department)).toList();}}
@RestController @RequestMapping("/api/dashboard") @CrossOrigin(originPatterns={"http://localhost:[*]","http://127.0.0.1:[*]"}) class DashboardController {final StudentRepository students;final FacultyRepository faculty;final AttendanceRepository attendance;DashboardController(StudentRepository s,FacultyRepository f,AttendanceRepository a){students=s;faculty=f;attendance=a;}@GetMapping("/stats") Map<String,Object> stats(){List<Attendance> today=attendance.findByDate(LocalDate.now());long present=today.stream().filter(a->a.status!=AttendanceStatus.ABSENT).count();return Map.of("totalStudents",students.count(),"totalFaculty",faculty.count(),"presentToday",present,"absentToday",today.size()-present,"attendancePercent",today.isEmpty()?0:Math.round(100.0*present/today.size()));}}
